new=r'''// holderText(id): the text of a data holder, or '' when it is missing.
function holderText(id) {
  var el = document.getElementById(id);
  return el ? String(el.textContent || '').trim() : '';
}

// clearWinner(): back to a neutral face-off. The 'neutral' state's effect and play()'s reset.
function clearWinner() {
  var sides = document.querySelectorAll('.matchup-side');
  for (var i = 0; i < sides.length; i++) {
    sides[i].classList.remove('matchup-win', 'matchup-lose');
    var mark = sides[i].querySelector('.matchup-verdict');
    if (mark) mark.textContent = '';
  }
  var root = document.querySelector('.matchup');
  if (root) root.classList.remove('matchup-locked');
}

// clearPick(): the Clear press — neutral look AND the reported winner field emptied.
function clearPick() {
  var holder = document.getElementById('f5');
  if (holder) holder.textContent = '';
  clearWinner();
}

// paintWinner(): mark the side the winner holder (f5) names; quiet when it names none.
function paintWinner(animate) {
  var winner = sideEl(holderText('f5'));
  var locked = false;
  var root = document.querySelector('.matchup');
  if (root) locked = root.classList.contains('matchup-locked');
  clearWinner();
  if (locked && root) root.classList.add('matchup-locked');
  if (!winner) return;
  var word = holderText('f17') || 'WINNER';
  var sides = document.querySelectorAll('.matchup-side');
  for (var i = 0; i < sides.length; i++) {
    var isWinner = sides[i] === winner;
    sides[i].classList.add(isWinner ? 'matchup-win' : 'matchup-lose');
    var mark = sides[i].querySelector('.matchup-verdict');
    if (mark) mark.textContent = isWinner ? word : '';
  }
  if (animate) {
    var badge = winner.querySelector('.matchup-verdict');
    if (badge) gsap.fromTo(badge, { scale: 1.25, opacity: 0 }, { scale: 1, opacity: 1, duration: 0.45 / motionSpeed(), ease: 'back.out(2)' });
  }
}

// pickRed() / pickBlue(): the two decision states' calls. Each writes the reported field
// itself, so a press paints the right corner whether or not the host also sent the value.
function pickRed() { var h = document.getElementById('f5'); if (h) h.textContent = 'A'; paintWinner(true); }
function pickBlue() { var h = document.getElementById('f5'); if (h) h.textContent = 'B'; paintWinner(true); }
function applyWinner() { paintWinner(true); }

// applyLock(): the decision is final. Repaints from the holder first, so a recovery snap
// straight into 'locked' still shows the winner.
function applyLock() {
  var root = document.querySelector('.matchup');
  if (root) root.classList.add('matchup-locked');
  paintWinner(false);
  var badge = document.querySelector('.matchup-win .matchup-verdict');
  if (badge) gsap.fromTo(badge, { scale: 1.12 }, { scale: 1, duration: 0.35 / motionSpeed(), ease: 'back.out(2.4)' });
}

// compRepaint(): set-once words, logo backings, empty lines — after every update() and on play().
function compRepaint() {
  var words = [['.matchup-corner-a', 'f15'], ['.matchup-corner-b', 'f16'], ['.matchup-bout-word', 'f18']];
  for (var i = 0; i < words.length; i++) {
    var el = document.querySelector(words[i][0]);
    if (el) { el.textContent = holderText(words[i][1]); el.style.display = el.textContent ? '' : 'none'; }
  }
  var recs = document.querySelectorAll('.matchup-record-word');
  var rw = holderText('f19');
  for (var r = 0; r < recs.length; r++) { recs[r].textContent = rw; recs[r].style.display = rw ? '' : 'none'; }
  var plates = [['.matchup-side-a .matchup-plate', 'f13', 'f6'], ['.matchup-side-b .matchup-plate', 'f14', 'f7']];
  for (var p = 0; p < plates.length; p++) {
    var plate = document.querySelector(plates[p][0]);
    if (!plate) continue;
    var light = holderText(plates[p][1]).toLowerCase() === 'light';
    plate.classList.toggle('matchup-plate-light', light);
    plate.classList.toggle('matchup-plate-dark', !light);
    var img = document.getElementById(plates[p][2]);
    plate.classList.toggle('matchup-plate-empty', !(img && img.getAttribute('src')));
  }
  var optional = ['f8', 'f9', 'f10', 'f11', 'f12', 'f3', 'f4'];
  for (var o = 0; o < optional.length; o++) {
    var line = document.getElementById(optional[o]);
    if (line && line.parentNode) line.parentNode.classList.toggle('matchup-empty', !/\S/.test(line.textContent || ''));
  }
  var recRows = document.querySelectorAll('.matchup-record');
  for (var q = 0; q < recRows.length; q++) {
    var val = recRows[q].querySelector('.matchup-note');
    recRows[q].classList.toggle('matchup-empty', !(val && /\S/.test(val.textContent || '')));
  }
  var bout = document.querySelector('.matchup-bout');
  var num = document.getElementById('f12');
  if (bout) bout.classList.toggle('matchup-empty', !(num && /\S/.test(num.textContent || '')));
  // A winner already on air takes a renamed word at once.
  var badge = document.querySelector('.matchup-win .matchup-verdict');
  if (badge) badge.textContent = holderText('f17') || 'WINNER';
}

// compClearMarks(): play()'s visual reset — the neutral face-off, whatever the last run left.
function compClearMarks() {
  clearPick();
}

if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', compRepaint);
else compRepaint();

'''
