        ],
        "transitions": [
          { "from": "enter", "to": "redWins", "trigger": "operator", "event": "winRed" },
          { "from": "enter", "to": "blueWins", "trigger": "operator", "event": "winBlue" },
          { "from": "neutral", "to": "redWins", "trigger": "operator", "event": "winRed" },
          { "from": "neutral", "to": "blueWins", "trigger": "operator", "event": "winBlue" },
          { "from": "redWins", "to": "blueWins", "trigger": "operator", "event": "winBlue" },
          { "from": "blueWins", "to": "redWins", "trigger": "operator", "event": "winRed" },
          { "from": "redWins", "to": "locked", "trigger": "operator", "event": "lock" },
          { "from": "blueWins", "to": "locked", "trigger": "operator", "event": "lock" },
          { "from": "redWins", "to": "neutral", "trigger": "operator", "event": "clear" },
          { "from": "blueWins", "to": "neutral", "trigger": "operator", "event": "clear" },
          { "from": "locked", "to": "neutral", "trigger": "operator", "event": "clear" },
          { "from": "locked", "to": "out", "trigger": "operator", "event": "next" }
        ]
      }
    ],
    "controls": [
      { "event": "winRed", "label": "Win {f0|Red}", "order": 1, "section": "Decision", "set": { "f5": "A" } },
      { "event": "winBlue", "label": "Win {f1|Blue}", "order": 2, "section": "Decision", "set": { "f5": "B" } },
      { "event": "lock", "label": "Lock it in", "order": 3, "section": "Decision" },
      { "event": "clear", "label": "Clear", "order": 4, "section": "Decision", "destructive": true, "set": { "f5": "" } }
    ]
  }
'''
s=s[:a]+machine+s[b:]
open(p,'w').write(s)
